#[allow(unused_variables)] fn ability_2_0_0_rule(q: &dyn Query, asker: &Asker, attacker: ObjectId, defender: Target) -> bool { let source = asker.source; let asker = &Asker::new(source, q.controller(source)); !((q.history().this_turn().iter().any(|r| matches!(r.event, Event::TurnBegan { extra: true, .. }))) && attacker == asker.source) }

